import assert from 'node:assert/strict';
import cp from 'node:child_process';
import { syncBuiltinESMExports } from 'node:module';
import { EventEmitter } from 'node:events';
import { PassThrough } from 'node:stream';
import { rm } from 'node:fs/promises';
import { dirname } from 'node:path';
let nonce; const calls = []; const originalSpawn = cp.spawn; const originalLog = console.log; let captured;
cp.spawn = (command, args) => {
  assert.equal(command, 'docker');
  const child = new EventEmitter(); child.stdout = new PassThrough(); child.stderr = new PassThrough(); child.stdin = new PassThrough(); child.kill = () => true;
  calls.push(args[0]);
  let out = '', diagnostic = '', code = 0;
  if (args[0] === 'info') out = '{}';
  else if (args[0] === 'image') out = '{}';
  else if (args[0] === 'run') { nonce = args[args.indexOf('--label') + 1].split('=')[1]; out = 'owned-fixture-id'; }
  else if (args[0] === 'inspect' && args[args.indexOf('--format') + 1].includes('imageId')) { code = 1; diagnostic = 'forced metadata inspection failure'; }
  else if (args[0] === 'inspect') out = JSON.stringify({ id: 'owned-fixture-id', owner: nonce });
  else if (args[0] === 'rm') { code = 1; diagnostic = 'forced cleanup removal failure'; }
  else assert.fail('Unexpected Docker operation');
  queueMicrotask(() => { child.stdout.end(out); child.stderr.end(diagnostic); child.emit('close', code); });
  return child;
};
syncBuiltinESMExports(); console.log = text => { captured = JSON.parse(text); };
try {
  await import('./scripts/pilot-rehearsal.mjs?review-cleanup-failure');
  assert.equal(captured.status, 'failed'); assert.equal(captured.failure.kind, 'AggregateError');
  assert.equal(captured.cleanupComplete, true); assert.equal(captured.resources, undefined);
  originalLog(JSON.stringify({ reproduction: 'startup cleanup failure', commands: calls, output: { status: captured.status, failure: captured.failure, cleanupComplete: captured.cleanupComplete, resourcesPresent: !!captured.resources, cleanupFailuresPresent: !!captured.cleanupFailures }, actualFixtureContainerRemoved: false, realDockerCalls: 0 }));
} finally { cp.spawn = originalSpawn; syncBuiltinESMExports(); console.log = originalLog; if (captured?.reportPath) await rm(dirname(captured.reportPath), { recursive: true }); process.exitCode = 0; }

